/**
 * emit to subscription queries of type FindTrainingRun,
 * but only if the id matches
 *
 * @param		entity	TrainingRun
 */
	protected void emitFindTrainingRun( TrainingRun entity ) {
		LOGGER.info("handling emitFindTrainingRun" );
		
	    queryUpdateEmitter.emit(FindTrainingRunQuery.class,
	                            query -> query.getFilter().getTrainingRunId().equals(entity.getTrainingRunId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllTrainingRun
	 * 
	 * @param		entity	TrainingRun
	 */
	protected void emitFindAllTrainingRun( TrainingRun entity ) {
		LOGGER.info("handling emitFindAllTrainingRun" );
		
	    queryUpdateEmitter.emit(FindAllTrainingRunQuery.class,
	                            query -> true,
	                            entity);
	}

